def bbox_coords(g, pred):
    pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if pred(x)]
    return min(r for r,c in pts),max(r for r,c in pts),min(c for r,c in pts),max(c for r,c in pts)
def get_transforms(a):
    mats=[]; m=a
    for k in range(4):
        if k: m=[list(row) for row in zip(*m[::-1])]
        mats.append(m)
        mats.append([row[::-1] for row in m])
    out=[]; seen=set()
    for m in mats:
        t=tuple(map(tuple,m))
        if t not in seen: out.append(m);seen.add(t)
    return out
def infer(g):
    r0,r1,c0,c1=bbox_coords(g,lambda x:x not in (0,8))
    kr=[row[c0:c1+1] for row in g[r0:r1+1]]
    q0,q1,p0,p1=bbox_coords(g,lambda x:x==8)
    s=(q1-q0+1)//len(kr)
    mh=(q1-q0+1)//s; mw=(p1-p0+1)//s
    mask=[[all(g[q0+i*s+di][p0+j*s+dj]==8 for di in range(s) for dj in range(s)) for j in range(mw)] for i in range(mh)]
    opts=[]
    for m in get_transforms(kr):
        occ=[[x!=0 for x in row] for row in m]
        if occ==mask: opts.append(m)
    return kr,s,(q0,q1,p0,p1),mask,opts
for name,inp,out in [('d1',D1I,D1O),('d2',D2I,D2O)]:
    kr,s,b,mask,opts=infer(inp)
    print(name,'key',kr,'s',s,'bbox',b,'mask',mask,'opts',len(opts))
    for o in opts: print(o)

def transf_named(a):
    result=[]; m=a
    for k in range(4):
        if k: m=[list(row) for row in zip(*m[::-1])]
        result.append((f'rot{k*90}',m))
        result.append((f'rot{k*90}_flipH',[row[::-1] for row in m]))
    return result
